"""Occurrence data for records 556--559. Run from the task workspace."""
import csv, json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
items=[]
talks=[]
problems=[]
corrections=[]

def talk(record,date,speaker,pages,title,summary):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))

def item(record,pages,kind,title,notes,statement,fate,refs=(),cls='E',reconstruction='',status='',literal='correct with missing hypotheses',match='exact',verification='read the result',development='annotated',problem='',worth='',confidence='high',speaker='',area=''):
    n=1+sum(i['record']==record for i in items)
    d=dict(id=f'1981-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of 11 November 2026: '+(status or 'the stated qualified result is established; the literal notebook shorthand should be read with the hypotheses above.'),literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence,area=area or ('Representation theory and symplectic geometry' if record<558 else 'Index theory and spectral geometry'))
    if speaker:d['speaker']=speaker
    items.append(d)
    save()
    return d['id']

def corr(page,place,reads,should,evidence,typ='faithful_error',applies='both'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))

def save():
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        (ROOT/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(556,'1982-03-15','A. A. Kirillov','P001013-P001018','Orbit geometry, multiplicities, and student research topics',r'The actual heading and mathematical discussion occupy P001014--P001016; the wider catalogue range also includes Haefliger and Givental. Kirillov proposes topics on multiplicities, illustrates the geometry of an \(SU(3)\) orbit and its diagonal projection, and relates a recent Guillemin--Sternberg preprint to an index on a reduced space. Gelfand adds questions about duality, difference calculus and hypergeometric functions. The final remarks connect torus convexity with Newton polyhedra. The missing quotient in the multiplicity formula is mathematically consequential.')
item(556,'P001014','problem','Geometric computation of compact-group weight multiplicities',r'Weight multiplicities and restriction to subgroups are proposed as student topics; Guillemin--Sternberg are said to give an answer in principle.',r'For a compact connected Lie group \(G\), an integral dominant weight \(\lambda\), and a maximal torus \(T\), determine \(m_\lambda(\nu)=\dim\operatorname{Hom}_T(\mathbb C_\nu,V_\lambda)\), and interpret it as a quantization of the symplectic reduction of the corresponding prequantized orbit.',r'The notebook supplies circulation evidence for a preprint by March 1982. \citet{guilleminsternberg1982multiplicities} was published in October 1982; the Kähler result and the later general symplectic/singular extensions must be distinguished. \citet[Introduction and \S2.4]{meinrenkensjamaar1999singular} give the latter, with a July 1997 preprint preceding the 1999 publication.',('guilleminsternberg1982multiplicities','meinrenkensjamaar1999singular'),cls='B',reconstruction=r'The choice of a highest weight, prequantum bundle and reduction is our precise version of a topic, not a claim that the notebook states the general singular theorem.',problem='GP-1981-41',status=r'The compact prequantizable Hamiltonian case has an index-theoretic solution, including singular reductions in the specified Riemann--Roch sense. No new open problem is inferred from this student topic.',match='partial')
item(556,'P001014','remark','The unspecified hyperbolic multiplicity programme',r'Hyperbolic algebras are described by a Cartan matrix having a negative eigenvalue; multiplicities and Macdonald are mentioned.',r'A symmetrizable generalized Cartan matrix is hyperbolic only if it is indecomposable of indefinite type and every proper connected principal submatrix is of finite or affine type. A negative eigenvalue alone does not impose these conditions. No matrix, module, weight, or proposed multiplicity formula is specified.',r'This is not enough to identify a single problem or match a later theorem. The general root-multiplicity discussion earlier this year and the compact-group problem are distinct. Search by the phrase and the cited surname yielded no uniquely recoverable target.',(),cls='F',literal='not determinable',match='none found',verification='unresolved lead',status='The programme is identifiable by subject only; an exact fate cannot be assigned. No claim that hyperbolic multiplicities are generally uncomputed is made.',confidence='low')
item(556,'P001014-P001015','construction','The regular SU(3) orbit and its hexagonal diagonal image',r'The skew-Hermitian trace-zero matrix \(X\) has fixed \(\operatorname{tr}X^2=c_2\), \(\operatorname{tr}X^3=c_3\). Its orbit is six-dimensional and its diagonal projection is drawn as a hexagon.',r'For three distinct real eigenvalues \(\lambda_1>\lambda_2>\lambda_3\), with sum zero, the orbit of \(i\operatorname{diag}(\lambda_1,\lambda_2,\lambda_3)\) is \(SU(3)/T^2\), of real dimension six. Its diagonal image is the convex hull of the six permutations of \(\lambda\). For repeated eigenvalues the orbit dimension and polygon degenerate.',r'\citet[Introduction and Theorem 1]{atiyah1982convexity} explicitly relate the general torus theorem to the older Schur--Horn and coadjoint-orbit cases. The notebook attributes the orbit picture to \citet{berezingelfand1956spherical}; that attribution is retained as a partial historical match, not evidence that every later quantization assertion is in the 1956 paper.',('atiyah1982convexity','berezingelfand1956spherical'),reconstruction='Regularity and the ordered real eigenvalues make the sketch precise.',match='partial')
item(556,'P001015','claim','Dimensions and singular values of the torus moment map',r'A regular fibre of the diagonal projection \(p\) has dimension four; the diagram marks internal walls where the fibre becomes singular.',r'For the Hamiltonian action of the effective two-torus on a regular six-dimensional orbit, a regular level \(\mu^{-1}(\nu)\) has dimension four and its quotient by a locally free torus action has dimension two. Values with positive-dimensional isotropy are critical, including the boundary of the moment polygon; an interior-wall drawing is not a complete classification by itself.',r'This is the regular-value theorem together with Hamiltonian reduction. \citet[\S2.1]{meinrenkensjamaar1999singular} distinguish the level set from its quotient and explain the stratification when regularity fails.',('meinrenkensjamaar1999singular',),reconstruction='The quotient and the qualification about the diagram are editorial additions.',match='partial')
item(556,'P001015','claim','SU(3) weight hexagons and multiplicity layers',r'Irreducible representations are indexed by two integers; a hexagonal weight diagram has increasing multiplicities towards a central triangle.',r'For \(SU(3)\), dominant integral highest weights are \(a\omega_1+b\omega_2\), \(a,b\in\mathbb Z_{\ge0}\). Weight multiplicities are Weyl-invariant, have the familiar successive-layer pattern, and are bounded by \(\min(a,b)+1\). Only weights in the appropriate root-lattice coset occur; a drawn polygon does not make every lattice point a weight.',r'The compact semisimple character formula in \citet{kirillov1968characters} provides the established representation-theoretic setting. The diagram is expository and does not constitute a new multiplicity theorem.',('kirillov1968characters',),verification='publisher metadata checked',match='partial',confidence='medium',status='The highest-weight classification and the type A2 multiplicity pattern are classical. The sketch is not a specification of a new formula.')
item(556,'P001015','claim','Riemann–Roch multiplicity requires a reduced space',r'The notes write \(X=p^{-1}(y_0)\) and \(\langle e^B\operatorname{Td},X\rangle=\text{multiplicity}\), for large parameters.',r'At a regular integral weight \(\nu\), with a free effective torus action and the descended prequantum line bundle \(L_\nu\), the relevant index is \(\int_{M_\nu}\operatorname{ch}(L_\nu)\operatorname{Td}(TM_\nu)\), where \(M_\nu=\mu^{-1}(\nu)/T\). Appropriate positivity identifies this index with the relevant holomorphic multiplicity. Orbifold stabilizers require an orbifold index, and singular levels require a separately defined singular Riemann--Roch number.',r'The 1982 Guillemin--Sternberg result and \citet[\S2.4]{meinrenkensjamaar1999singular} support the reduced-space interpretation. The scanned formula genuinely omits the quotient, so this is a faithful mathematical error rather than a translation slip.',('guilleminsternberg1982multiplicities','meinrenkensjamaar1999singular'),cls='B',literal='false as written',reconstruction=r'We supply \(M_\nu\), the descended line bundle, and the index interpretation. The notebook does not justify using an ordinary Todd integral on a singular quotient.',problem='GP-1981-41',match='partial')
item(556,'P001015','question','An unspecified duality between groups and representations',r'Gelfand calls the duality between groups and their representations the main question.',r'No category of groups, dual object, topology, or universal property is specified. Pontryagin, Tannakian and orbit-method dualities are different possible interpretations.',r'No exact theorem can be selected from this sentence without importing a programme into the record.',(),cls='F',literal='not determinable',match='none found',verification='unresolved lead',status='The question remains a historical programme statement, not an indexed mathematical conjecture.',confidence='low',speaker='I. M. Gelfand')
item(556,'P001015','method','Falling factorials as a basis for finite differences',r'Gelfand contrasts \(d(x^n)/dx=nx^{n-1}\) with \(\Delta x^{\underline n}=n x^{\underline{n-1}}\).',r'For \(\Delta f(x)=f(x+1)-f(x)\) and \(x^{\underline n}=x(x-1)\cdots(x-n+1)\), \(\Delta x^{\underline n}=n x^{\underline{n-1}}\) for \(n\ge1\); equivalently \(\Delta\binom{x}{n}=\binom{x}{n-1}\).',r'This follows immediately by factoring the two falling factorials. It is the classical Newton-series basis underlying \citet{mahler1958interpolation}, not a theorem originating in this talk.',('mahler1958interpolation',),literal='correct',speaker='I. M. Gelfand',verification='publisher metadata checked')
item(556,'P001016','claim','Orbit volume and representation dimension need a normalization and a shift',r'The invariant orbit measure is unique up to scale and can be normalized so that its volume is the representation dimension.',r'On a compact homogeneous orbit the invariant measure is unique up to a positive scalar. Rescaling it to any prescribed positive total volume is tautologically possible. With the standard Kirillov--Kostant Liouville normalization, the dimension formula instead uses the orbit through \(\lambda+\rho\), not generally the unshifted orbit through \(\lambda\).',r'The character formula of \citet{kirillov1968characters} is the relevant established source. The note is correct as a freedom to choose scale, but cannot by itself identify that scale with the canonical symplectic normalization.',('kirillov1968characters',),verification='publisher metadata checked',match='partial',confidence='medium')
item(556,'P001016','method','Fractional differentiation and the Euler hypergeometric integral',r'The displayed integral for the \(p\)-th derivative of \(x^k(1-x)^\ell\) has kernel \((x-t)^{-p-1}\) and no gamma prefactor.',r'Initially for \(0<x<1\), \(\operatorname{Re}k>-1\) and \(\operatorname{Re}p<0\), define \[D^p f(x)=\frac1{\Gamma(-p)}\int_0^x(x-t)^{-p-1}f(t)\,dt.\] Then \[D^p[x^k(1-x)^\ell]=\frac{\Gamma(k+1)}{\Gamma(k-p+1)}x^{k-p}{}_2F_1(-\ell,k+1;k-p+1;x),\] with consistent branches and meromorphic continuation in the parameters. In particular \(D^p x^k=\Gamma(k+1)x^{k-p}/\Gamma(k-p+1)\).',r'The substitution \(t=xu\) reduces this directly to the classical Euler integral; compare \citet[Eq.~15.6.1]{nist2026hypergeometric}. The missing \(1/\Gamma(-p)\) is visible in the scan. Ordinary derivatives at nonnegative integral \(p\) require continuation or the corresponding fractional-calculus definition, not a divergent literal integral.',('nist2026hypergeometric',),literal='false as written',speaker='I. M. Gelfand',reconstruction='The branch, convergence domain and normalized fractional operator are supplied here.')
item(556,'P001016','remark','The programme of multivariable hypergeometric functions',r'There is said to be no satisfactory theory of hypergeometric functions of several variables.',r'This is an assessment of the state of a subject, without a specified class of differential systems or a criterion of completeness. A precise later framework is the \(A\)-hypergeometric system attached to an integer matrix and a complex parameter.',r'\citet{gelfandzelevinskykapranov1989hypergeometric} developed a major framework, preceded by the 1987--1988 announcements listed in that paper. This is a thematic successor, not proof that every intended multivariable question was solved.',('gelfandzelevinskykapranov1989hypergeometric',),cls='F',literal='not determinable',match='thematic only',verification='publisher metadata checked',status='Several precise multivariable theories are established; the unrestricted evaluative sentence has no single true-or-false resolution.',confidence='medium',speaker='I. M. Gelfand')
item(556,'P001016','theorem','Atiyah convexity and the torus approach to representations',r'Atiyah is cited for the convexity of the momentum image of a torus action; Khovanskii and Kazarnovskii are mentioned in relation to Newton polyhedra.',r'For a Hamiltonian torus acting on a compact connected symplectic manifold, the moment-map image is a convex polytope, the convex hull of the images of the fixed-point components, and its fibres are connected. Compactness, connectedness and a genuine Hamiltonian moment map are essential.',r'\citet[Theorems 1--2]{atiyah1982convexity}, received 27 March 1981 and published in 1982, gives the result; the previous-year item 1980-508.15 already records its circulation. The names of Khovanskii and Kazarnovskii identify an adjacent Newton-polyhedron programme, but no specific enumerative formula is stated here.',('atiyah1982convexity',),reconstruction='The precise theorem is separated from the unformulated application programme.',match='exact')
corr('P001014','Hyperbolic Cartan matrix','Having a negative eigenvalue','Add indecomposability, indefinite type, and finite/affine proper connected principal submatrices for the standard hyperbolic definition.','The scan contains only the negative-eigenvalue parenthesis; it does not specify a matrix.','ambiguity')
corr('P001015','Orbit label after the invariants',r'\Omega_{c_1,c_2}',r'\Omega_{c_2,c_3}','The same discussion fixes tr X^2 and tr X^3; the inconsistent subscripts are present in the scan.')
corr('P001015','Riemann–Roch multiplicity formula',r'X=p^{-1}(y_0)',r'X=\mu^{-1}(\nu)/T, with descended prequantum data','A four-dimensional level set is not the two-dimensional reduced symplectic space used in the multiplicity theorem. The scan has no quotient.')
corr('P001016','Fractional derivative integral','Integral without a prefactor',r'Insert 1/\Gamma(-p), initially Re p<0, then continue','Direct beta-integral evaluation and the scan confirm the missing normalization.')

talk(557,'1982-03-29','A. B. Givental','P001016-P001020','Relative symplectic normal forms and Lagrangian planes',r'The manuscript heading is on P001017 and the talk ends on P001018. A relative Darboux theorem leads to local symplectic extension, the symplectic geometry of rays and obstacle problems, and the invariant alternating form on an odd symmetric power of the standard \(SL_2\)-module. An intervention attributed to Goldsheid asks for uniform approximation of a Lagrangian plane by a product of lines in fixed coordinate symplectic planes. That last question has much stronger quantifiers than the coordinatewise observation following it.')
item(557,'P001017','theorem','Relative Darboux theorem for a smooth submanifold',r'If \(\omega_0|_{TN}=\omega_1|_{TN}\), then near each point of \(N\) a diffeomorphism fixing \(N\) pulls \(\omega_1\) back to \(\omega_0\).',r'Let \(N\) be a smooth embedded submanifold of a smooth manifold and let \(\omega_0,\omega_1\) be symplectic forms near \(x\in N\), with equal pullbacks to \(N\). There are neighbourhood germs and a diffeomorphism germ \(g\), identity on \(N\), such that \(g^*\omega_1=\omega_0\). No constant-rank assumption on the restricted form is needed for this local statement.',r'\citet[Chapter 2, \S1.3, Theorem I and proof, pp.~24--25]{arnoldgivental1990symplectic} state and prove this result. The Russian chapter appeared in 1985 and the English version in 1990. The March 1982 notebook is earlier circulation evidence, not proof that the 1985 chapter was the first announcement.',('arnoldgivental1990symplectic',),cls='A',reconstruction='We interpret the displayed U-to-U map as an equivalence of neighbourhood germs; one fixed invariant open set is unnecessary.',status='Established as the relative Darboux–Givental theorem; the cited proof covers precisely equality of pullbacks.')
item(557,'P001017','method','Moser’s deformation argument relative to a submanifold',r'Choose \(g_t^*\omega_t=\omega_0\), differentiate, and solve an ordinary differential equation; a point gives Darboux.',r'First align the two bilinear forms at the base point by a linear map fixing \(T_xN\). On a sufficiently small neighbourhood, the interpolating forms are nondegenerate. Choose a primitive of \(\omega_1-\omega_0\) that vanishes as an ambient covector along \(N\); solve \(\iota_{V_t}\omega_t=-\alpha\), so \(V_t|_N=0\), and integrate. Equality of pullbacks alone does not say the unadjusted straight-line path is nondegenerate.',r'The full relative argument is given in \citet[Chapter 2, \S1.3]{arnoldgivental1990symplectic}. The homotopy method is older; the cited source explains the preliminary linear adjustment omitted in the notebook.',('arnoldgivental1990symplectic',),cls='E',match='partial',reconstruction='The linear adjustment and vanishing of the primitive as an ambient covector are supplied proof details.')
item(557,'P001017','question','When does a two-form extend to an ambient symplectic form?',r'The question asks when a two-form is the restriction of a symplectic form; closedness is named. Gelfand asks first for the vector-space structure.',r'Let \(N\subset M\) be a submanifold germ with \(\dim M\) even and let \(\beta\) be a smooth two-form on \(N\). It extends locally near \(x\) to a symplectic form on \(M\) if and only if \(d\beta=0\) near \(x\) and \(\dim\ker\beta_x\le\operatorname{codim}_M N\).',r'\citet[Chapter 2, \S1.3, Extension Theorem, p.~25]{arnoldgivental1990symplectic} gives the exact criterion. The pointwise algebraic question omits closedness legitimately, whereas a smooth symplectic extension cannot.',('arnoldgivental1990symplectic',),cls='A',problem='GP-1981-42',reconstruction='The ambient dimension and corank inequality are absent from the question and supplied from the later theorem.',status='The local smooth extension problem is solved with this criterion; it does not assert a global embedding theorem.')
item(557,'P001017','construction','The symplectic space of oriented rays',r'The space of straight lines in \(\mathbb R^3\) is symplectic and is identified in Arnold’s explanation with \(T^*\mathbb R^2\).',r'The space of oriented affine lines in \(\mathbb R^3\) is globally \(T^*S^2\): direction \(u\in S^2\) and closest point \(v\perp u\). Reduction of the unit-speed geodesic flow supplies its canonical symplectic form. A direction chart gives \(T^*\mathbb R^2\) only locally. Reversing the line orientation is anti-symplectic, so the unoriented quotient is not endowed with this same symplectic form.',r'\citet[Example 1]{givental1983lagrangian} explicitly identifies the reduced space as \(T^*S^{n-1}\). The result is standard before the talk; the later paper verifies the exact geometric context.',('givental1983lagrangian',),literal='correct with missing hypotheses',reconstruction='Orientation and the local meaning of the affine cotangent chart are necessary qualifications.')
item(557,'P001017','claim','Extremals and the obstacle example',r'The space of extremals of any variational problem is said to be symplectic; a point and a sphere produce a two-dimensional family.',r'For a regular finite-dimensional first-order variational problem, the Legendre transform identifies local Cauchy data with a symplectic phase space. On a regular fixed-energy level one may reduce by the nonvanishing Hamiltonian flow. Families generated by a fixed initial point can then give Lagrangian subvarieties; obstacle tangencies can create singularities. Degenerate Lagrangians or singular quotients require a separate treatment.',r'\citet[Examples 1--2, Theorem and Corollary]{givental1983lagrangian}, received 19 July 1982 and published in 1983, connects generic obstacle singularities to open swallowtails. This supplies a concrete development of the example, not a proof of the unrestricted word “any”.',('givental1983lagrangian',),cls='A',literal='false as written',match='partial',reconstruction='Regularity, reduction, and genericity are explicit modern hypotheses not supplied by the notebook.')
item(557,'P001017-P001018','construction','The symplectic odd binary-form representation',r'The space of binary forms of degree \(2n-1\) has Darboux coefficients \(q_j,p_j\) and an \(SL_2(\mathbb R)\)-invariant \(\omega=\sum dp_j\wedge dq_j\).',r'Write the dehomogenized polynomial as \[F(w)=\sum_{j=1}^n q_j\frac{w^{2n-j}}{(2n-j)!}+\sum_{j=1}^n(-1)^{n-j}p_j\frac{w^{j-1}}{(j-1)!}.\] The irreducible module \(\operatorname{Sym}^{2n-1}\mathbb R^2\) has an invariant nondegenerate alternating form, unique up to scalar; the displayed coefficient normalization makes it \(\sum dp_j\wedge dq_j\).',r'\citet[Example 2]{givental1983lagrangian} publishes this representation and its use in singularity models. The representation-theoretic alternating form itself is classical; the application is developed in the subsequent paper.',('givental1983lagrangian',),cls='E',reconstruction='The alternating signs in the second sum fix the overwritten sign on P001017. Different Hamiltonian/sign conventions in the publication are equivalent after a coordinate sign change.')
item(557,'P001018','construction','Translation Hamiltonian and reduction by q1',r'\(w\mapsto w+t\) is generated by \(h=q_n^2/2-q_{n-1}p_n-\cdots-q_1p_2\); \(q_1\) is a first integral and \(q_1=1,p_1=1\) are imposed.',r'With \(\omega=\sum dp_j\wedge dq_j\) and \(\iota_{X_h}\omega=dh\), the translation flow has \(\dot q_1=0\), \(\dot q_j=q_{j-1}\) for \(j>1\), \(\dot p_n=q_n\), and \(\dot p_j=-p_{j+1}\) for \(j<n\). The hypersurface \(q_1=1\) has characteristic direction \(\partial_{p_1}\); its quotient is symplectic of dimension \(2n-2\). Fixing \(p_1=1\) chooses a slice, rather than a second conserved quantity.',r'\citet[Example 2]{givental1983lagrangian} gives the corresponding Hamiltonian representation and reduction. Direct coefficient differentiation of \(F(w+t)\) checks the notebook signs under the stated convention.',('givental1983lagrangian',),cls='A',reconstruction='The Hamiltonian sign convention and the quotient meaning of the slice are supplied.',status='The construction is established; no claim that p1 is preserved by the translation Hamiltonian is justified.')
gold=item(557,'P001018','question','Goldsheid’s uniform approximation by coordinate-product Lagrangians',r'Goldsheid asks whether every Lagrangian \(L\subset\mathbb R^{2n}\) admits \(L_1=\operatorname{span}(\alpha_je_j+\beta_jf_j)\) with \(\|P_L-P_{L_1}\|\le1/\sqrt2\); even any constant less than one independent of \(n\) would suffice.',r'Use the standard Euclidean and symplectic structures, with \(Je_j=f_j\). Must every Lagrangian \(n\)-plane admit one nonzero vector in each prescribed coordinate plane \(\operatorname{span}(e_j,f_j)\), whose direct sum \(K\) satisfies \(\|P_L-P_K\|_{2\to2}\le2^{-1/2}\)? The weaker question asks for a universal \(c<1\) for all \(n\).',r'The scan unambiguously gives an operator norm and a dimension-independent requirement. Searches under Goldsheid/Goldsheyd/\ru{Гольдшейд}, Lagrangian projections, symmetric-unitary diagonal approximation, Math-Net author records, arXiv and MathOverflow located no exact resolution. \citet[Theorem 3.4]{mehrmannpoloni2012doubling} bounds individual entries of a permuted Lagrangian graph basis; that does not supply the requested uniform operator norm. The development below proves a Fourier-matrix counterexample to the sharp constant at \(n=6\), a universal lower obstruction \(\cos(\pi/8)\), and a dimension-dependent upper bound.',('mehrmannpoloni2012doubling',),cls='C',literal='correct',match='partial',development='developed in this chapter',problem='GP-1981-40',worth='Worth developing because the exact finite-dimensional optimization is explicit and admits certified partial bounds while preserving the unresolved uniform quantifier.',status=r'We disprove the proposed \(1/\sqrt2\) constant in dimension \(n=6\). More generally, any universal constant must be at least \(\cos(\pi/8)\). We establish \(\cos(\pi/(2n))<1\) for each fixed \(n\), but do not resolve the existence of a universal \(c\in[\cos(\pi/8),1)\). No exact later resolution of that weaker question was located in this bounded search.',confidence='medium',speaker='I. Ya. Goldsheid')
item(557,'P001018','claim','Coordinatewise closeness does not control the gap of the spans',r'For every \(j\), one can choose \(\varphi_j=\alpha_je_j+\beta_jf_j\) with \(\sin\angle(\varphi_j,L)\le1/\sqrt2\).',r'The compression of \(P_L\) to each coordinate \(J\)-plane has trace one, so its largest eigenvalue is at least \(1/2\), proving the coordinatewise claim. This supplies no bound for all linear combinations of the chosen vectors. Indeed for \(n\ge2\), \(v=(1,\ldots,1)/\sqrt n\) and \(L=\mathbb Rv\oplus i v^\perp\) give \(\operatorname{dist}(f_j,L)=1/\sqrt n\), yet \(\|P_L-P_{i\mathbb R^n}\|=1\).',r'The observation in the notebook is correct. The explicit counterexample to the inference about the span is proved and independently checked in our development; it is not a counterexample to Goldsheid’s existential question.',(),cls='E',literal='correct',match='none found',verification='read the result',problem='GP-1981-40',reconstruction='The trace proof and the example separating the quantifiers are ours.',status='The elementary coordinatewise statement is verified; its use as a proof of uniform subspace approximation would be invalid.')
corr('P001017','Darboux coordinates for odd binary forms','Overwritten sign before the p_(n−1) term','Use a minus sign before p_(n−1) and alternating signs thereafter.','The full alternating formula is forced by the displayed symplectic form and checked by differentiating F(w+t). The overwritten mark in the scan alone is not decisive.','ambiguity')
corr('P001017','Space of lines identified with cotangent space',r'T^*R^2',r'Locally T^*R^2; globally oriented lines form T^*S^2.','Givental 1983, Example 1, explicitly uses the reduced T^*S^(n−1). Orientation is not stated in the notes.','ambiguity')
corr('P001017','Any variational problem','Extremals of any variational problem form a symplectic space','Require regularity of the variational problem and a smooth reduction where used.','A degenerate Lagrangian yields a degenerate Legendre transform; the literal universal quantifier exceeds the valid construction.')

